// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { CheckIcon, CopyIcon, QrCodeIcon } from 'lucide-react'

import { DemoStage, PanelChrome, type Build } from '@/app/demos/stage'
import { Qr } from '@/app/demos/stage/Qr'

import { BASE, CAPTIONS, DEFAULT_BASE, FIELDS, PIECES, URL_OUT } from './script'

const CONTENT = FIELDS.findIndex((field) => field.key === 'utm_content')

const build: Build = ({ tl, q, step, final, move, click, type, wait, cursorOut }) => {
  const snap = (index: number, at?: string) => {
    const piece = PIECES[index]
    const field = FIELDS.findIndex((item) => item.key === piece.key)
    tl.to(
      q(`field-${field}`),
      { borderColor: piece.color, duration: 0.15, yoyo: true, repeat: 1 },
      at,
    )
    tl.fromTo(
      q(`piece-${index}`),
      { opacity: 0, x: -40, rotation: -6, scale: 0.8 },
      { opacity: 1, x: 0, rotation: 0, scale: 1, duration: 0.45, ease: 'back.out(2.5)' },
      '<',
    )
  }

  step(0)
  move('field-base', { ax: 0.6, at: 0.2 })
  click('field-base')
  tl.to(q('base-text'), { text: '', duration: 0.25 }, '<0.1')
  type('base-text', BASE, { speed: 0.03 })
  type('piece-base', BASE, { at: '<', speed: 0.03 })

  step(1, '+=0.3')
  PIECES.forEach((piece, index) => {
    if (piece.key !== 'utm_content') snap(index, index === 0 ? undefined : '+=0.15')
  })

  step(2, '+=0.4')
  move(`field-${CONTENT}`, { ax: 0.6 })
  click(`field-${CONTENT}`)
  type(`value-${CONTENT}`, FIELDS[CONTENT].value, { speed: 0.06 })
  snap(PIECES.length - 1, '+=0.05')

  step(3, '+=0.4')
  move('copy')
  click('copy')
  tl.to(q('copy-icon'), { opacity: 0, duration: 0.1 }, '<')
  tl.fromTo(
    q('copy-done'),
    { opacity: 0, scale: 0.5 },
    { opacity: 1, scale: 1, duration: 0.25, ease: 'back.out(3)' },
    '<',
  )
  move('qr-button', { at: '+=0.2' })
  click('qr-button')
  tl.fromTo(
    q('qr'),
    { clipPath: 'inset(0% 0% 100% 0%)', opacity: 1 },
    { clipPath: 'inset(0% 0% 0% 0%)', duration: 0.8, ease: 'power2.inOut' },
    '<',
  )
  tl.fromTo(q('scan'), { opacity: 1, y: 0 }, { y: 118, duration: 0.8, ease: 'power2.inOut' }, '<')
  tl.to(q('scan'), { opacity: 0, duration: 0.2 })
  cursorOut('+=0.2')
  final()
  wait(1.4)
}

export default function Demo() {
  return (
    <DemoStage
      label="UTM Builder tagging a landing page link piece by piece, then copying it and making a QR code"
      steps={CAPTIONS}
      build={build}
    >
      <PanelChrome>
        <div className="flex h-full gap-3">
          <div className="w-[208px] shrink-0 space-y-1.5">
            <div
              data-d="field-base"
              className="rounded-md border border-line bg-canvas/80 px-2 py-1"
            >
              <p className="text-[8.5px] text-muted">Landing page URL</p>
              <p className="h-[14px] truncate font-mono text-[9.5px] text-ink">
                <span data-d="base-text">{DEFAULT_BASE}</span>
              </p>
            </div>
            {FIELDS.map((field, index) => (
              <div
                key={field.key}
                data-d={`field-${index}`}
                className="flex h-7 items-center gap-2 rounded-md border border-line bg-canvas/80 px-2"
              >
                <span
                  className="w-[72px] shrink-0 font-mono text-[9px]"
                  style={{ color: field.color }}
                >
                  {field.key}
                </span>
                <span
                  data-d={`value-${index}`}
                  className="truncate font-mono text-[9.5px] text-ink"
                >
                  {index === CONTENT ? '' : field.value}
                </span>
              </div>
            ))}
          </div>
          <div className="flex min-w-0 flex-1 flex-col gap-2">
            <p className="text-[10px] font-medium text-ink-soft">Your link</p>
            <div className="flex min-h-[92px] flex-wrap content-start gap-1 rounded-lg border border-line bg-canvas/80 p-2 font-mono text-[9.5px]">
              <span data-d="piece-base" className="rounded-md bg-white/[0.06] px-1.5 py-1 text-ink">
                {DEFAULT_BASE}
              </span>
              {PIECES.map((piece, index) => (
                <span
                  key={piece.key}
                  data-d={`piece-${index}`}
                  className="rounded-md border px-1.5 py-1 opacity-0"
                  style={{
                    color: piece.color,
                    borderColor: piece.color,
                    backgroundColor: `${piece.color}14`,
                  }}
                >
                  {piece.text}
                </span>
              ))}
            </div>
            <div className="flex gap-1.5">
              <span
                data-d="copy"
                className="flex items-center gap-1 rounded-md border border-line-strong px-2 py-1 text-[9.5px] text-ink-soft"
              >
                <span className="relative size-3">
                  <span data-d="copy-icon" className="absolute inset-0">
                    <CopyIcon className="size-3" />
                  </span>
                  <span
                    data-d="copy-done"
                    className="absolute inset-0 text-[var(--accent)] opacity-0"
                  >
                    <CheckIcon className="size-3" />
                  </span>
                </span>
                Copy
              </span>
              <span
                data-d="qr-button"
                className="flex items-center gap-1 px-1 py-1 text-[9.5px] text-[var(--accent)] underline"
              >
                <QrCodeIcon className="size-3" /> Generate QR
              </span>
            </div>
            <div className="relative w-fit overflow-hidden rounded-md">
              <div data-d="qr" className="opacity-0">
                <Qr text={URL_OUT} size={118} />
              </div>
              <span
                data-d="scan"
                className="absolute inset-x-0 top-0 h-0.5 bg-[var(--accent)] opacity-0 shadow-[0_0_10px_var(--accent)]"
              />
            </div>
          </div>
        </div>
      </PanelChrome>
    </DemoStage>
  )
}
